CREATE TRIGGER staff_hardware_auth_state_lock BEFORE UPDATE OF hardware_only_enabled_at, active, auth_revision ON public.staff_user FOR EACH ROW WHEN (((old.hardware_only_enabled_at IS DISTINCT FROM new.hardware_only_enabled_at) OR (old.active IS DISTINCT FROM new.active) OR (old.auth_revision IS DISTINCT FROM new.auth_revision))) EXECUTE FUNCTION app.lock_staff_hardware_auth_state();
